steps.script:
const ok = await $exists("div[role='feed'] div[role='article']", 10000);
if (!ok) return { done: false };
await new Promise(r => setTimeout(r, 2000));
return { done: true };

const target = (__input__ && __input__.postCount) || 10;
const seen = new Set((__lastResult__ && __lastResult__.seenSignatures) || []);

// Deep scroll: several increments per iteration to push the lazy loader.
let scrolledAny = false;
for (let i = 0; i < 3; i++) {
  const r = await $scrollBy(window.innerHeight * 1.5, "div[role='feed']");
  if (r.scrolled) scrolledAny = true;
  await new Promise(resolve => setTimeout(resolve, 1200));
}
if (!scrolledAny) {
  const r2 = await $scrollToBottom();
  scrolledAny = r2.scrolled;
  await new Promise(resolve => setTimeout(resolve, 1500));
}

const articles = await $list("div[role='feed'] div[role='article']");
let postLike = 0;
for (const a of articles) {
  const t = (a.textContent || '').slice(0, 160);
  if (!t.trim()) continue;
  seen.add(t);
  // count only post-like signatures: has a timestamp marker (年/月/天/小时/分钟/昨天)
  if (/\d{4}年|\d{1,2}月\d{1,2}日|昨天|\d+小时|\d+天前|\d+分钟/.test(t)) postLike++;
}
const uniqueCount = seen.size;
const stalled = ((__lastResult__ && __lastResult__.stalled) || 0) + (scrolledAny ? 0 : 1);
if (postLike >= target) return { done: true, uniqueCount, seenSignatures: [...seen].slice(0, 100) };
if (stalled >= 8 && postLike > 0) return { done: true, uniqueCount, seenSignatures: [...seen].slice(0, 100), exhausted: true };
return { done: false, uniqueCount, postLike, stalled, seenSignatures: [...seen].slice(0, 100) };

const target = (__input__ && __input__.postCount) || 10;
const start = (__lastResult__ && __lastResult__.nextStart) || 0;

const total = await $count("div[role='feed'] div[role='article'][aria-posinset]");
if (total === 0 && start === 0) {
  return { done: true, accumulated: [], nextStart: 0 };
}

const records = await $extractWithHover("div[role='feed'] div[role='article'][aria-posinset]", {
  postUrl: { selector: "a[href*='multi_permalinks'], a[href*='story_fbid'], a[href*='/posts/'], a[href*='/permalink/']", attr: 'href' },
  timeLabel: { selector: "a[role='link'][href*='story_fbid'][aria-label], a[role='link'][href*='/posts/'][aria-label], a[role='link'][href*='multi_permalinks'][aria-label]", attr: 'aria-label' },
  authorName: "div[data-ad-rendering-role='profile_name'] h3 a span, div[data-ad-rendering-role='profile_name'] a span",
  authorHref: { selector: "div[data-ad-rendering-role='profile_name'] h3 a, div[data-ad-rendering-role='profile_name'] a", attr: 'href' },
  content: "div[data-ad-rendering-role='story_message'] div[data-ad-preview='message']",
  contentHtml: { selector: "div[data-ad-rendering-role='story_message'] div[data-ad-preview='message']", attr: 'innerHTML' },
  html: { selector: '', attr: 'outerHTML' }
}, {
  hover: {
    anchorSel: "div[data-ad-rendering-role='profile_name'] a, a[href*='/groups/']:not([href*='/user/'])",
    popoverSel: "div[data-hovercard], div[role='dialog']",
    timeoutMs: 3000
  },
  allowEmpty: true,
  containerRange: [start, start + 5]
});

const labelRecords = await $extractListMulti("div[role='feed'] div[role='article'][aria-posinset]", {
  ariaLabels: { selector: "div[role='aria-label'], div[role][aria-label]", attr: 'aria-label' },
  // Full outerHTML of EVERY action-bar button so we can pair each count span
  // with ITS OWN button's aria-label (semantic mapping, not positional).
  actionBtnHtml: { selector: "div[role='button'][aria-label]", attr: 'outerHTML' }
}, { allowEmpty: true });

const mediaRecords = await $extractListMulti("div[role='feed'] div[role='article'][aria-posinset]", {
  mediaUrls: { selector: "img[src*='scontent']", attr: 'src' }
}, { allowEmpty: true });

// Classify a button's aria-label into likes / comments / shares by SEMANTICS.
// A post may lack the comment button entirely — then its count span simply
// does not exist and comments stays '' (never borrow the share count).
function btnKind(label) {
  const s = (label || '').trim();
  if (!s) return '';
  if (/评论|留言|回覆|回复|comment/i.test(s)) return 'comments';
  if (/分享|转发|共享|发送给好友|分享给|share/i.test(s)) return 'shares';
  if (/^赞$|^点赞|like/i.test(s)) return 'likes';
  return ''; // 留下心情 / 写评论… / other non-count controls
}

function parseCounts(labels, btnHtmls) {
  const out = { likes: '', comments: '', shares: '' };
  const seen = {};
  for (const bh of (btnHtmls || [])) {
    if (!bh) continue;
    const lm = bh.match(/aria-label="([^"]*)"/);
    const kind = btnKind(lm ? lm[1] : '');
    if (!kind || seen[kind]) continue;
    // count span inside THIS button only
    const cm = bh.match(/<span[^>]*xhkezso[^>]*>([^<]+)<\/span>/);
    if (cm && /^\d+([.,]\d+)*万?$/.test(cm[1].trim())) {
      out[kind] = cm[1].trim();
      seen[kind] = true;
    }
  }
  // Reaction aria-labels are a fallback for likes only (never comments/shares).
  if (!out.likes) {
    const reactionTotal = [];
    for (const l of (labels || [])) {
      const s = (l || '').trim();
      if (!s) continue;
      const rl = s.match(/^(?:赞|大爱|哇|抱抱|伤心|生气|哈哈|关爱)[：:]\s*([\d,.]+\s*万?)(?:\s*(?:位用户|人))?$/);
      if (rl) {
        reactionTotal.push(parseFloat(rl[1].replace(/[万,]/g, '')) * (rl[1].indexOf('万') >= 0 ? 10000 : 1));
      }
    }
    if (reactionTotal.length) out.likes = String(reactionTotal.reduce((s, v) => s + v, 0));
  }
  return out;
}

const prev = (__lastResult__ && __lastResult__.accumulated) || [];
const batch = (records || []).map((r, i) => {
  const idx = start + i;
  r.mediaUrls = (mediaRecords[idx] && mediaRecords[idx].mediaUrls) || [];
  r.ariaLabels = (labelRecords[idx] && labelRecords[idx].ariaLabels) || [];
  const c = parseCounts(r.ariaLabels, (labelRecords[idx] && labelRecords[idx].actionBtnHtml) || []);
  r.likes = c.likes;
  r.comments = c.comments;
  r.shares = c.shares;
  return r;
});
const accumulated = prev.concat(batch);
const nextStart = start + 5;

if (accumulated.length >= target + 3 || nextStart >= total) {
  return { done: true, accumulated, nextStart, total };
}
return { done: false, accumulated, nextStart, total };

const target = (__input__ && __input__.postCount) || 10;
const keyword = (__input__ && __input__.keyword) || '';
const raw = (__lastResult__ && __lastResult__.accumulated) || [];
const posts = [];
let idx = 0;

const pickCount = (m) => (m ? m[1].trim() : '');

function decodeEntities(s) {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x2F;/gi, '/')
    .replace(/&(?:#x200D|zwj);/gi, '\u200D')
    .replace(/&(?:#xFE0F|#x20E3);/gi, '\uFE0F');
}

function htmlToText(html) {
  if (!html) return '';
  let s = html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(?:div|p|li|ul|ol|h[1-6]|tr|blockquote)>/gi, '\n')
    .replace(/<(?:img|video)[^>]*>/gi, '')
    .replace(/<[^>]+>/g, '');
  s = decodeEntities(s);
  s = s.replace(/\n[ \t]+/g, '\n').replace(/\n{3,}/g, '\n\n');
  return s.trim();
}

function classifyHref(href) {
  if (/\/groups\/[^/?]+\/user\//.test(href)) return '账号';
  if (/\/groups\/[^/?]+/.test(href)) return '小组';
  if (/profile\.php/.test(href) || /facebook\.com\/[^/?]+/.test(href)) return '账号';
  return '';
}

for (const rec of raw) {
  const hasPermalink = rec.postUrl && /story_fbid|\/posts\/|\/permalink\/|multi_permalinks/.test(rec.postUrl);
  if (!hasPermalink) continue;
  idx += 1;

  const html = rec.html || '';
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const fullText = doc.body.textContent || '';

  // ---- hovercards ----
  const hoverInfos = [];
  const seenEntities = new Set();
  for (const card of (rec.hovercards || [])) {
    if (!card || !card.htmlSnippet) continue;
    const cdoc = new DOMParser().parseFromString(card.htmlSnippet, 'text/html');
    if (!cdoc.querySelector('[aria-label="链接预览"], [aria-label="关闭链接预览"]')) continue;
    if (!cdoc.querySelector('h3')) continue;
    const h3a = cdoc.querySelector('h3 a[href]');
    const href = h3a ? h3a.getAttribute('href') : '';
    const type = classifyHref(href);
    if (!type) continue;
    const ctext = cdoc.body.textContent || '';
    const kv = {};
    let entityKey = '';
    if (type === '小组') {
      const m = href.match(/\/groups\/([^/?]+)/);
      if (m) kv.groupId = m[1];
      kv.groupLink = 'https://www.facebook.com/groups/' + (m ? m[1] : '');
      kv.groupName = h3a ? h3a.textContent.trim() : (card.anchorText || '').trim();
      const mm = ctext.match(/([\d,.]+\s*万?)\s*位成员/);
      kv.memberCount = mm ? mm[0] : '';
      kv.privacy = /公开/.test(ctext) ? '公开' : (/私密/.test(ctext) ? '私密' : '');
      const img = cdoc.querySelector('image, img');
      if (img) kv.groupIcon = img.getAttribute('xlink:href') || img.getAttribute('src') || '';
      entityKey = 'group:' + (m ? m[1] : kv.groupName);
      if (seenEntities.has(entityKey)) continue;
      seenEntities.add(entityKey);
      hoverInfos.push({ link: href, htmlSnippet: card.htmlSnippet, type: '小组', role: '发帖小组', ...kv });
    } else {
      let userId = '', userLink = '';
      const gu = href.match(/\/groups\/[^/?]+\/user\/([\w.]+)/);
      const idm = href.match(/[?&]id=(\d+)/);
      const vm = href.match(/facebook\.com\/([^/?]+)/);
      if (gu) { userId = gu[1]; userLink = 'https://www.facebook.com/profile.php?id=' + gu[1]; }
      else if (idm) { userId = idm[1]; userLink = 'https://www.facebook.com/profile.php?id=' + idm[1]; }
      else if (vm) { userId = vm[1]; userLink = 'https://www.facebook.com/' + vm[1]; }
      kv.accountId = userId;
      kv.accountLink = userLink;
      kv.accountName = h3a ? h3a.textContent.trim() : (card.anchorText || '').trim();
      const fm = ctext.match(/([\d,.]+\s*万?)\s*位粉丝/);
      kv.followerCount = fm ? fm[0] : '';
      const img = cdoc.querySelector('image, img');
      if (img) kv.avatar = img.getAttribute('xlink:href') || img.getAttribute('src') || '';
      const attrs = [];
      const attrPatterns = [
        ['所在地', /所在地：([^来自已关\n]{2,20})/],
        ['来自', /来自：([^已目添\n]{2,20})/],
        ['目前就职', /目前就职：([^曾经已\n]{2,40})/],
        ['曾经就读', /曾经就读：([^已添\n]{2,40})/],
        ['标签', /(公共主页\s*·\s*[^,，。;；\n]{2,20})/]
      ];
      for (const pair of attrPatterns) {
        const m = ctext.match(pair[1]);
        if (m) attrs.push(pair[0] + '：' + m[1].trim());
      }
      kv.attributes = attrs;
      entityKey = 'user:' + userId;
      if (seenEntities.has(entityKey)) continue;
      seenEntities.add(entityKey);
      hoverInfos.push({ link: href, htmlSnippet: card.htmlSnippet, type: '账号', role: '主发帖人', ...kv });
    }
  }

  // ---- media ----
  const mediaUrls = [...doc.querySelectorAll("img[src*='scontent'], video[poster]")]
    .map(e => e.getAttribute('src') || e.getAttribute('poster') || '').filter(Boolean);

  // ---- likes / comments / shares ----
  // Step 4 computed these from the action-bar count spans in fixed order
  // [likes, comments, shares] — these are authoritative. Only fill EMPTY
  // fields from explicit aria-label / text phrasings. NEVER re-derive a
  // non-empty field, and NEVER split concatenated "展开<digits>" strings.
  let likes = (rec.likes || '').trim();
  let comments = (rec.comments || '').trim();
  let shares = (rec.shares || '').trim();

  const labels = rec.ariaLabels || [];
  const RE_COMMENT = /([\d,.]+\s*万?)\s*(?:条|则|个|篇)(?:评论|留言|回覆|回复)/;
  const RE_SHARE = /([\d,.]+\s*万?)\s*(?:次|则|个)?(?:分享|转发|共享)/;
  if (!likes || !comments || !shares) {
    for (const a of labels) {
      if (typeof a !== 'string') continue;
      if (!likes) {
        const rl = a.match(/^(?:赞|大爱|哇|抱抱|伤心|生气|哈哈|关爱)：?([\d,.]+\s*万?)(?:\s*(?:位用户|人))?$/);
        if (rl) likes = rl[1].trim();
      }
      if (!comments) { const m = a.match(RE_COMMENT); if (m) comments = pickCount(m); }
      if (!shares) { const m = a.match(RE_SHARE); if (m) shares = pickCount(m); }
    }
  }
  if (!likes || !comments || !shares) {
    for (const el of doc.querySelectorAll('[aria-label]')) {
      const a = el.getAttribute('aria-label') || '';
      if (!likes) { const rl = a.match(/^(?:赞|大爱|哇|抱抱|伤心|生气|哈哈|关爱)：?([\d,.]+\s*万?)(?:\s*(?:位用户|人))?$/); if (rl) likes = rl[1].trim(); }
      if (!comments) { const m = a.match(RE_COMMENT); if (m) comments = pickCount(m); }
      if (!shares) { const m = a.match(RE_SHARE); if (m) shares = pickCount(m); }
    }
  }
  // plain-text explicit phrasings (label word required — no digit-splitting)
  if (!comments) { const m = fullText.match(RE_COMMENT); if (m) comments = pickCount(m); }
  if (!comments) { const m = fullText.match(/([\d,.]+\s*万?)\s*则留言/); if (m) comments = pickCount(m); }
  if (!shares) { const m = fullText.match(RE_SHARE); if (m) shares = pickCount(m); }
  if (!shares) { const m = fullText.match(/([\d,.]+\s*万?)\s*人分享(?:了)?/); if (m) shares = pickCount(m); }
  if (!likes) { const m = fullText.match(/([\d,.]+\s*万?)\s*(?:人赞|个赞|条赞)/); if (m) likes = pickCount(m); }

  // ---- time ----
  let time = (rec.timeLabel || '').trim();
  if (!time || !(/年|月|日|小时|天|分钟|昨天/.test(time))) {
    const m = fullText.match(/\d{4}年\d{1,2}月\d{1,2}日|\d{1,2}月\d{1,2}日|昨天|\d+小时前|\d+分钟前|\d+天前|\d+分钟/);
    time = m ? m[0] : (time || '');
  }

  // ---- location ----
  let location = '';
  const lm = fullText.match(/(?:发自于?|来自于?)\s*([^·\n，,;；]{2,20})/);
  if (lm) location = lm[1].trim();

  // ---- content ----
  let content = htmlToText(rec.contentHtml || '');
  if (!content) content = (rec.content || '').replace(/\s*收起\s*$/, '').trim();
  else content = content.replace(/\s*收起\s*$/, '').trim();

  const idm = (rec.postUrl || '').match(/story_fbid=(\w+)|\/posts\/([\w-]+)|multi_permalinks=(\w+)/);
  posts.push({
    index: idx,
    postId: idm ? (idm[1] || idm[2] || idm[3]) : '',
    hoverInfos,
    time,
    location,
    content,
    mediaUrls,
    likes,
    comments,
    shares,
    html
  });
  if (posts.length >= target) break;
}
return { keyword, posts };
